export type {
  NumericCdfDistribution,
  NumericCdfPoint,
  PredictionDistribution,
} from "./prediction-distribution";

// Forecast-cell definitions and AI analyst reasoning scripts.
// Each cell is a self-contained record with a pre-written reasoning stream
// that the AgentReasoning component plays back with simulated streaming.
//
// The reasoning is illustrative — numbers and tool-call results are
// constructed to demonstrate the integrated stack (encoded law,
// PolicyEngine microsim, public data cells) rather than to be live forecasts.

export type ForecastCellType = "data" | "policy" | "conditional";

export type Unit =
  | "count"
  | "percent"
  | "gbp_billions"
  | "usd"
  | "usd_millions"
  | "usd_billions"
  // Non-canonical variant admitted by the 2026-08-03 auto-roll — registered
  // snapshots are immutable, so the site tolerates it. Canonical is
  // "usd_billions" and registration-side enum validation is the follow-up.
  | "billions USD"
  | "usd_monthly"
  | "thousands"
  | "millions"
  | "million_cubic_feet"
  | "per_1000_live_births"
  | "ratio"
  | "minutes"
  | "percent_growth"
  | "index_points";

export interface HistoricalPoint {
  // Optional only for already-published pre-2.5.10 cells. Current generated
  // cells must carry this presentation-independent identity.
  period?: {
    type: "month" | "quarter" | "year" | "fiscal_year" | "week_ending";
    value: string;
  };
  label: string;
  value: number;
}

export type PredictionCadence = "weekly" | "monthly" | "quarterly" | "annual";

export type ForecastHorizon =
  | "next_release"
  | "plus_3m"
  | "plus_12m"
  | "long_run"
  | "quarterly_path"
  | "threshold";

export type ResolutionPolicy = "first_print" | "fixed_vintage" | "final";

export type CountryCode = "US" | "UK" | "CA" | "AU" | "EA" | "JP" | "BE";

export interface ForecastSeriesMetadata {
  seriesId: string;
  country: CountryCode;
  cadence: PredictionCadence;
  horizon: ForecastHorizon;
  horizonLabel: string;
  priority: "P0" | "P1" | "P2";
  source: string;
  resolutionPolicy: ResolutionPolicy;
  resolutionLatency: string;
  benchmark?: string;
  chainableQuestions: string[];
}

export type PredictionPackKind =
  | "calibration"
  | "data"
  | "method"
  | "model"
  | "policy";

export interface PredictionPackReference {
  packId: string;
  version: string;
  label: string;
  kind: PredictionPackKind;
  summary: string;
}

export type PredictionPackSetMode = "none" | "with_packs" | "ensemble";

export interface PredictionPackSet {
  packSetId: string;
  label: string;
  mode: PredictionPackSetMode;
  packs: PredictionPackReference[];
  notes?: string;
}

export type PredictionRunActivityArtifactType =
  | "prompt"
  | "command"
  | "stdout"
  | "stderr"
  | "codex_stdout_jsonl"
  | "codex_stderr_log"
  | "codex_events_jsonl"
  | "codex_last_message"
  | "codex_trace"
  | "draft_forecast"
  | "review_prompt"
  | "pre_submit_review"
  | "review_disposition"
  | "revision_prompt"
  | "raw_response"
  | "parsed_cell"
  | "normalized_cell"
  | "run_distribution"
  | "cells_with_activity"
  | "validation_report"
  | "model_candidates"
  | "baseline_inputs"
  | "manifest"
  // Derived-ensemble runs (scripts/median_rollout_ensemble.py) reference
  // their inputs and exact output distribution as first-class artifacts.
  | "constituent_manifest"
  | "derived_distribution";

export interface PredictionRunActivityArtifact {
  artifactType: PredictionRunActivityArtifactType;
  path: string;
  sha256: string;
  bytes: number;
  createdAt: string;
  observationRefs?: LedgerObservationReference[];
  custodyRootSha256?: string;
  hashMode?: string;
}

export interface LedgerObservationReference {
  observationId: string;
  dataPointId: string;
  periodLabel: string;
  observedAt: string;
  value: number;
  unit: Unit;
}

export type PredictionPreSubmitReviewStatus =
  | "not_requested"
  | "completed"
  | "draft_failed"
  | "review_failed"
  | "revision_failed";

export type PredictionPreSubmitReviewFindingSeverity =
  | "info"
  | "warning"
  | "blocking";

export type PredictionPreSubmitReviewDecision =
  | "accepted"
  | "partially_accepted"
  | "rejected"
  | "not_applicable";

export interface PredictionPreSubmitReviewFinding {
  findingId: string;
  severity: PredictionPreSubmitReviewFindingSeverity;
  rubricItem: string;
  summary: string;
  actionRequested?: string;
}

export interface PredictionPreSubmitReviewDisposition {
  findingId: string;
  decision: PredictionPreSubmitReviewDecision;
  rationale: string;
  forecastChanged: boolean;
}

export interface PredictionPreSubmitReviewWorkflow {
  schemaVersion: "thesis_pre_submit_review_v1";
  status: PredictionPreSubmitReviewStatus;
  requestedAt: string;
  reviewer: {
    agent: string;
    model?: string;
    promptVersion: "pre-submit-review-v0.1";
    commandHash?: string;
  };
  draftArtifactPath?: string;
  reviewArtifactPath?: string;
  revisionPromptPath?: string;
  findings: PredictionPreSubmitReviewFinding[];
  dispositions: PredictionPreSubmitReviewDisposition[];
  summary: string;
}

export interface PredictionRunMetadata {
  kind: "recorded-agent-run";
  runAt: string;
  agent: string;
  model: string;
  sourceContext: string[];
  runLabel?: string;
  runDescription?: string;
  packSet?: PredictionPackSet;
  // Versioned-agent attribution (agents/thesis-analyst): semver of the agent
  // definition plus content hashes of its system prompt and skill set, so a
  // published run is reproducible against an exact agent.
  agentVersion?: string;
  promptHash?: string;
  toolPolicyHash?: string;
  provenance?: "ci" | "local_operator_attested";
  generationTicket?: {
    ticketId: string;
    ticketPath: string;
  };
  custodyRootSha256?: string;
  promptMode?: string;
  inputBundleHash?: string;
  aggregationAlgorithmVersion?: string;
  constituentRuns?: Array<{
    manifestPath: string;
    manifestSha256?: string;
    manifestBytes?: number;
    custodyRootSha256: string;
    runAt: string;
  }>;
  activityLog?: PredictionRunActivityArtifact[];
  preSubmitReview?: PredictionPreSubmitReviewWorkflow;
}

export interface ResolvedOutcome {
  value: number;
  resolvedAt: string;
  source: string;
  sourceUrl?: string;
  note?: string;
}

export type ReasoningStep =
  | { kind: "heading"; text: string }
  | { kind: "text"; text: string }
  | {
      kind: "tool"; // call to PolicyEngine microsim or other data lookup
      call: string;
      result: string;
      tool?: string; // optional tool name override; defaults to policyengine.simulate
    }
  | { kind: "math"; text: string } // styled equation/weighting line
  | { kind: "forecast"; point: number; ciLow: number; ciHigh: number };

export interface ExternalSubmissionAttribution {
  /** Challenger identity: the GitHub account that submitted, e.g. "github:khs". */
  challenger: string;
  /** Self-declared per open-challenge rule 2; leaderboards segment by it. */
  systemType: "ai" | "human" | "hybrid";
}

export interface ForecastComparisonRun {
  variantId: string;
  label: string;
  description?: string;
  pointEstimate: number;
  ciLow: number;
  ciHigh: number;
  confidence?: number;
  drivers?: string[];
  predictionRun: PredictionRunMetadata;
  predictionDistribution?: PredictionDistribution;
  reasoning: ReasoningStep[];
  externalSubmission?: ExternalSubmissionAttribution;
}

export interface ForecastCell {
  slug: string;
  country?: CountryCode;
  type: ForecastCellType;
  title: string;
  question: string;
  unit: Unit;
  pointEstimate: number;
  ciLow: number;
  ciHigh: number;
  confidence: number; // 0.80 etc.
  resolutionDate: string; // ISO date, e.g. "2027-09-15"
  resolutionSource: string;
  resolutionSourceUrl?: string;
  resolutionRule: string;
  historicalContext: HistoricalPoint[];
  drivers: string[];
  dataPointId?: string; // for published public-data forecast cells
  policyParameter?: string; // for policy forecast cells
  conditionalOn?: string; // for conditional forecast cells
  series?: ForecastSeriesMetadata;
  predictionRun?: PredictionRunMetadata;
  comparisonRuns?: ForecastComparisonRun[];
  persistenceBaseline?: PersistenceBaselineRecord;
  resolvedOutcome?: ResolvedOutcome;
  predictionDistribution?: PredictionDistribution;
  reasoning: ReasoningStep[];
}

export interface PersistenceBaselineRecord {
  status: "available" | "unavailable";
  variantId: "time-series-prior";
  cutoff: string;
  targetDataPointId?: string;
  seriesId?: string;
  observationRefs: LedgerObservationReference[];
  reason?: string;
}

export interface ForecastRunEntry {
  variantId: string;
  label: string;
  description?: string;
  isPrimary: boolean;
  pointEstimate: number;
  ciLow: number;
  ciHigh: number;
  confidence: number;
  drivers: string[];
  predictionRun?: PredictionRunMetadata;
  packSet?: PredictionPackSet;
  predictionDistribution: PredictionDistribution;
  reasoning: ReasoningStep[];
  externalSubmission?: ExternalSubmissionAttribution;
}

export type ForecastRuntimeKind = "live-api" | "agent-run" | "static-mock";

export const LIVE_FORECAST_SLUGS = new Set([
  "spm-child-poverty-2025",
  "cpi-u-annual-2026",
  "ctc-expansion-cost-ty2026",
  "ctc-current-law-outlays-ty2026",
]);

export function getForecastRuntimeKind(
  forecastOrSlug: ForecastCell | string,
): ForecastRuntimeKind {
  const slug =
    typeof forecastOrSlug === "string" ? forecastOrSlug : forecastOrSlug.slug;
  if (LIVE_FORECAST_SLUGS.has(slug)) return "live-api";
  if (typeof forecastOrSlug !== "string" && forecastOrSlug.predictionRun) {
    return "agent-run";
  }
  return "static-mock";
}

export function getForecastRuntimeLabel(
  forecastOrSlug: ForecastCell | string,
): string {
  const kind = getForecastRuntimeKind(forecastOrSlug);
  if (kind === "live-api") return "Live API path";
  if (kind === "agent-run") return "Agent run";
  return "Static mock trace";
}

export function getForecastRunEntries(
  forecast: ForecastCell,
): ForecastRunEntry[] {
  const primaryDistribution =
    forecast.predictionDistribution ??
    buildNumericCdfFromInterval({
      pointEstimate: forecast.pointEstimate,
      ciLow: forecast.ciLow,
      ciHigh: forecast.ciHigh,
    });
  const primary: ForecastRunEntry = {
    variantId: "primary",
    label: forecast.predictionRun?.runLabel ?? "Headline",
    description: forecast.predictionRun?.runDescription,
    isPrimary: true,
    pointEstimate: forecast.pointEstimate,
    ciLow: forecast.ciLow,
    ciHigh: forecast.ciHigh,
    confidence: forecast.confidence,
    drivers: forecast.drivers,
    predictionRun: forecast.predictionRun,
    packSet: forecast.predictionRun?.packSet,
    predictionDistribution: primaryDistribution,
    reasoning: forecast.reasoning,
  };

  return [
    primary,
    ...(forecast.comparisonRuns ?? []).map(
      (run): ForecastRunEntry => ({
        variantId: run.variantId,
        label: run.label,
        description: run.description,
        isPrimary: false,
        pointEstimate: run.pointEstimate,
        ciLow: run.ciLow,
        ciHigh: run.ciHigh,
        confidence: run.confidence ?? forecast.confidence,
        drivers: run.drivers ?? forecast.drivers,
        predictionRun: run.predictionRun,
        packSet: run.predictionRun.packSet,
        predictionDistribution:
          run.predictionDistribution ??
          buildNumericCdfFromInterval({
            pointEstimate: run.pointEstimate,
            ciLow: run.ciLow,
            ciHigh: run.ciHigh,
          }),
        reasoning: run.reasoning,
        externalSubmission: run.externalSubmission,
      }),
    ),
  ];
}

export function getResolutionResult(
  forecast: ForecastCell,
): "inside" | "outside" | null {
  if (!forecast.resolvedOutcome) return null;
  const actual = forecast.resolvedOutcome.value;
  return forecast.ciLow <= actual && actual <= forecast.ciHigh
    ? "inside"
    : "outside";
}

